const b = $input.first().json.body;
const service = b.service || '(not set)';
const date = b.date || '(not set)';
const time = b.time || '(not set)';
const name = b.customerName || 'Valued Client';
const email = b.customerEmail || '';
const phone = b.customerPhone || 'Not provided';
const price = b.price || '';
const duration = b.duration || '';
const startISO = b.startISO || '';
const endISO = b.endISO || '';

const ownerHtml = '<!DOCTYPE html><html><head><meta charset="UTF-8"><style>body{font-family:Georgia,serif;background:#f9f9f9;margin:0;padding:40px 20px}.wrap{max-width:560px;margin:0 auto;background:#fff;border-radius:12px;overflow:hidden;box-shadow:0 2px 20px rgba(0,0,0,.08)}.hdr{background:#000;padding:32px 40px;text-align:center}.hdr h1{color:#fff;font-size:20px;letter-spacing:3px;margin:0;font-weight:400}.bdy{padding:40px}.intro{color:#444;font-size:15px;margin:0 0 24px}.row{display:flex;justify-content:space-between;align-items:center;padding:12px 0;border-bottom:1px solid #f0f0f0;font-size:14px}.row:last-child{border:0}.lbl{color:#888;text-transform:uppercase;letter-spacing:1px;font-size:11px}.val{color:#111;font-weight:500}.ftr{background:#f5f5f5;padding:20px 40px;text-align:center;color:#aaa;font-size:11px}</style></head><body><div class="wrap"><div class="hdr"><h1>NEW BOOKING</h1></div><div class="bdy"><p class="intro">A new appointment has been booked:</p><div class="row"><span class="lbl">Client</span><span class="val">' + name + '</span></div><div class="row"><span class="lbl">Email</span><span class="val">' + email + '</span></div><div class="row"><span class="lbl">Phone</span><span class="val">' + phone + '</span></div><div class="row"><span class="lbl">Service</span><span class="val">' + service + '</span></div><div class="row"><span class="lbl">Date</span><span class="val">' + date + '</span></div><div class="row"><span class="lbl">Time</span><span class="val">' + time + '</span></div><div class="row"><span class="lbl">Price</span><span class="val">' + price + '</span></div><div class="row"><span class="lbl">Duration</span><span class="val">' + duration + '</span></div></div><div class="ftr">SKY BEAUTY SALON &bull; Event added to your Google Calendar.</div></div></body></html>';

const customerHtml = '<!DOCTYPE html><html><head><meta charset="UTF-8"><style>body{font-family:Georgia,serif;background:#f9f9f9;margin:0;padding:40px 20px}.wrap{max-width:560px;margin:0 auto;background:#fff;border-radius:12px;overflow:hidden;box-shadow:0 2px 20px rgba(0,0,0,.08)}.hdr{background:#000;padding:40px;text-align:center}.logo{color:#fff;font-size:24px;letter-spacing:5px;margin:0 0 4px;font-weight:400}.tag{color:#555;font-size:10px;letter-spacing:3px;text-transform:uppercase;margin:0}.bdy{padding:40px}.greeting{font-size:18px;color:#111;margin:0 0 8px}.sub{font-size:14px;color:#666;margin:0 0 24px}.card{background:#f8f8f8;border-radius:8px;padding:24px;margin:0 0 24px}.card-t{font-size:10px;letter-spacing:2px;text-transform:uppercase;color:#888;margin:0 0 16px}.row{display:flex;justify-content:space-between;padding:10px 0;border-bottom:1px solid #ebebeb;font-size:13px}.row:last-child{border:0}.lbl{color:#888}.val{color:#111;font-weight:600}.note{font-size:13px;color:#666;line-height:1.7;margin:0}.ftr{background:#f5f5f5;padding:24px 40px;text-align:center;color:#aaa;font-size:11px;line-height:1.8}</style></head><body><div class="wrap"><div class="hdr"><p class="logo">SKY BEAUTY</p><p class="tag">Salon &amp; Studio</p></div><div class="bdy"><p class="greeting">Hi ' + name + ',</p><p class="sub">Your appointment is confirmed. We cannot wait to see you.</p><div class="card"><p class="card-t">Appointment Details</p><div class="row"><span class="lbl">Service</span><span class="val">' + service + '</span></div><div class="row"><span class="lbl">Date</span><span class="val">' + date + '</span></div><div class="row"><span class="lbl">Time</span><span class="val">' + time + '</span></div><div class="row"><span class="lbl">Duration</span><span class="val">' + duration + '</span></div><div class="row"><span class="lbl">Starting From</span><span class="val">' + price + '</span></div></div><p class="note">Need to reschedule? Please contact us at least 24 hours before your appointment.</p></div><div class="ftr">Sky Beauty Salon &bull; New York, NY</div></div></body></html>';

return [{
  json: {
    customerEmail: email,
    customerName: name,
    service: service,
    date: date,
    time: time,
    phone: phone,
    ownerHtml: ownerHtml,
    customerHtml: customerHtml,
    startISO: startISO,
    endISO: endISO,
    subject_owner: 'New Booking: ' + service + ' on ' + date + ' at ' + time,
    subject_customer: 'Your appointment is confirmed - Sky Beauty Salon'
  }
}];
